import{_ as t,o,c as a,a2 as r}from"./chunks/framework.YKbyQ3zk.js";const u=JSON.parse('{"title":"Supported versions","description":"","frontmatter":{},"headers":[],"relativePath":"supported-versions.md","filePath":"supported-versions.md"}'),s={name:"supported-versions.md"};function n(d,e,i,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="supported-versions" tabindex="-1">Supported versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported versions&quot;">​</a></h1><p>This page lists the versions of Node, pnpm, Convex, React, TanStack Start and the three browsers (Chromium, Firefox and WebKit) that EVO_AUTH has been tested on, and only those.</p><h2 id="what-the-list-means" tabindex="-1">What the list means <a class="header-anchor" href="#what-the-list-means" aria-label="Permalink to &quot;What the list means&quot;">​</a></h2><p>The table below lists what <a href="tested-versions.json"><code>tested-versions.json</code></a> records: for each recorded run, the commit, the date, and the version of each of the eight products. No script writes that file. A version that is newer, older or simply not on the list may work. Nobody has recorded that it does.</p><p>The table is empty while that file records no run.</p><h2 id="the-standalone-servers-node-range" tabindex="-1">The standalone server&#39;s Node range <a class="header-anchor" href="#the-standalone-servers-node-range" aria-label="Permalink to &quot;The standalone server&#39;s Node range&quot;">​</a></h2><p><code>@evo-auth/server</code> needs Node <code>&gt;=26.3 &lt;27</code>, the <code>engines</code> range of the package, because it uses the built-in <code>node:sqlite</code>. <code>@evo-auth/core</code> and its <code>evo-auth</code> command need only the older range on the <a href="./command-line.html">command-line page</a>. This is the range the package asks for. It is not a tested version: the package&#39;s own tests have been run on Node 26.3.0, and a Node version gets a row in the table below only when <code>tested-versions.json</code> records it, like any other. See <a href="./server.html#1-what-it-is-and-when-to-choose-it">the server guide</a>.</p><h2 id="nextjs" tabindex="-1">Next.js <a class="header-anchor" href="#nextjs" aria-label="Permalink to &quot;Next.js&quot;">​</a></h2><p><code>@evo-auth/nextjs</code> supports Next.js 16.4 and later with the App Router (its peer range is <code>next ^16.4.0</code>). It was built and measured on Next.js 16.4.6. Like any other version, a Next.js version gets a row in the table below only when <code>tested-versions.json</code> records it. See <a href="./nextjs.html">the Next.js guide</a>.</p><h2 id="react-router" tabindex="-1">React Router <a class="header-anchor" href="#react-router" aria-label="Permalink to &quot;React Router&quot;">​</a></h2><p><code>@evo-auth/react-router</code> supports React Router 8.5 and later in framework mode, with server rendering on the Node adapter (its peer range is <code>react-router ^8.5.0</code>, measured on 8.5.1); see <a href="./react-router.html">the React Router guide</a>.</p><h2 id="how-a-version-gets-added" tabindex="-1">How a version gets added <a class="header-anchor" href="#how-a-version-gets-added" aria-label="Permalink to &quot;How a version gets added&quot;">​</a></h2><ol><li>An entry for the version is added to <code>tested-versions.json</code>.</li><li>A row for that version is added to the table below, using the product names Node, pnpm, Convex, React, TanStack Start, Chromium, Firefox and WebKit.</li></ol><p><code>pnpm check:versions</code> reads the table between the two marker comments and nothing else on this page. It fails, naming the product and the version, when the table lists a version that no recorded entry has. An empty table passes. It also refuses a record or a table that does not have the documented shape.</p><h2 id="supported-versions-1" tabindex="-1">Supported versions <a class="header-anchor" href="#supported-versions-1" aria-label="Permalink to &quot;Supported versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Product</th><th>Version</th></tr></thead></table>',16)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
